mapper.select:
SELECT * FROM (
    SELECT contact.*, customer.owner_id AS scope_owner_id, customer.dept_id AS scope_dept_id
    FROM crm_contact contact JOIN crm_customer customer ON customer.customer_id = contact.customer_id AND customer.tenant_id = contact.tenant_id
    WHERE contact.deleted = 0 AND customer.deleted = 0
    AND contact.customer_id = #{query.customerId}
    AND contact.contact_name LIKE CONCAT('%', #{query.contactName}, '%')
    AND contact.status = #{query.status}
) scoped ORDER BY update_time DESC, contact_id DESC
